const $=s=>document.querySelector(s), D=window.STUDY;
let selected=0,views={},showSetting=true,rooms=false,arrival=false,layer=2,civic=0;
const saved=history.state?.worldDesign;
if(saved)({selected,views,showSetting,rooms,arrival,layer,civic}=saved);
const initial=location.hash.slice(1).split('-');if(initial[0]){const i=D.scenes.findIndex(s=>s.id===initial[0]);if(i>=0){selected=i;views[initial[0]]=Math.min(Number(initial[1])||0,D.scenes[i].views.length-1);}}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const external=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const reader=p=>'http://127.0.0.1:8931/read/web/'+p.book+'/'+p.chapter+'?hl='+p.verses;
function save(){history.replaceState({...history.state,worldDesign:{selected,views,showSetting,rooms,arrival,layer,civic}},'',`#${D.scenes[selected].id}-${views[D.scenes[selected].id]??0}`);}
function paintArt(){const s=D.scenes[selected];$('#art').innerHTML=worldArt(s.id,views[s.id]??0);$('#art').classList.toggle('evidence-only',!showSetting);$('#art').classList.toggle('rooms',rooms&&s.id==='household');$('#reconstruction').checked=showSetting;}
function closeReading(focus=false){$('#reading').hidden=true;$('#open-reading').setAttribute('aria-expanded','false');$('#open-reading').textContent='Examine the passage ↓';if(focus){$('#open-reading').focus({preventScroll:true});$('#open-reading').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
function choose(i){selected=i;closeReading();render();save();$('#announcement').textContent='Selected '+D.scenes[i].short+'. '+D.scenes[i].date;}
$('#stops').innerHTML=D.scenes.map((s,i)=>`<li><button data-stop="${i}" aria-controls="evidence"><span>0${i+1}</span>${esc(s.short)}</button></li>`).join('');
$('#scene-select').innerHTML=D.scenes.map((s,i)=>`<option value="${i}">0${i+1} · ${esc(s.short)}</option>`).join('');
$('#stops').addEventListener('click',e=>{const b=e.target.closest('button');if(b)choose(+b.dataset.stop)});$('#scene-select').onchange=e=>choose(+e.target.value);
function render(){const s=D.scenes[selected],v=s.views[views[s.id]??0];document.querySelectorAll('[data-stop]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stop===selected)));$('#scene-select').value=selected;$('#place').textContent=s.place;$('#date').textContent=s.date;$('#scene-title').textContent=s.title;paintArt();$('#view-buttons').innerHTML=s.views.map((v,i)=>`<button data-view="${i}" aria-pressed="${i===(views[s.id]??0)}" aria-controls="evidence"><b>${i+1}</b>${esc(v.label)}</button>`).join('');$('#art-caption').textContent=!showSetting?'Reconstructed surroundings faded. Numbered anchors point to source questions, not to measured or surviving fabric.':s.caption;$('#view-label').textContent=`Source question ${(views[s.id]??0)+1} / ${v.label}`;$('#evidence-title').textContent=v.title;$('#evidence-copy').textContent=v.evidence;$('#meaning').textContent=v.meaning;$('#limit').textContent=v.limit;$('#citations').innerHTML=v.sources.map(k=>external(D.sources[k].url,D.sources[k].label)).join('');$('#passages').innerHTML=v.passages.map(p=>`<a href="${reader(p)}">${esc(p.label)} · full context →</a>`).join('');$('#connection').textContent=s.connection;$('#next').textContent=selected<7?'Next: '+D.scenes[selected+1].short+' →':'Return to the village ↺';renderInvestigation();}
$('#view-buttons').onclick=e=>{const b=e.target.closest('button');if(!b)return;const n=+b.dataset.view;views[D.scenes[selected].id]=n;closeReading();render();save();$(`[data-view="${n}"]`).focus({preventScroll:true});$('#announcement').textContent=D.scenes[selected].views[n].title;};
$('#reconstruction').onchange=e=>{showSetting=e.target.checked;paintArt();$('#art-caption').textContent=showSetting?D.scenes[selected].caption:'Reconstructed surroundings faded. Numbered anchors point to source questions, not to measured or surviving fabric.';save()};
$('#reset').onclick=()=>{views[D.scenes[selected].id]=0;showSetting=true;rooms=false;arrival=false;layer=2;civic=0;closeReading();render();save();$('#announcement').textContent='This situation returned to its first source question.'};
$('#next').onclick=()=>{choose((selected+1)%8);$('#journey-title').scrollIntoView({block:'start',behavior:'instant'});};
$('#theme').onclick=()=>document.body.classList.toggle('dark');
$('#open-reading').onclick=()=>{if(!$('#reading').hidden){closeReading();return;}const v=D.scenes[selected].views[views[D.scenes[selected].id]??0];$('#reading-copy').innerHTML=v.passages.map(p=>`<article class="passage-block"><h5>${esc(p.label)} · World English Bible</h5><p>${(D.passageTexts[p.book+'/'+p.chapter+'/'+p.verses]||[]).map(t=>`<sup>${t.verse}</sup>${esc(t.text)}`).join(' ')}</p><a href="${reader(p)}">Read the complete chapter →</a></article>`).join('');$('#reading').hidden=false;$('#open-reading').setAttribute('aria-expanded','true');$('#open-reading').textContent='Retract passage ↑';};$('#close-reading').onclick=()=>closeReading(true);
function renderInvestigation(){const id=D.scenes[selected].id;let html='';
 if(id==='household')html=`<div><div><p class="eyebrow">Change the assumption, not the evidence</p><h4>The inequality survives.<br><em>Does the floor plan?</em></h4><label><input id="rooms" type="checkbox" ${rooms?'checked':''}> Propose separate dining spaces</label><label><input id="arrival" type="checkbox" ${arrival?'checked':''}> Propose different arrival times</label><p>Watch the dashed division in the scene above. It is an assumption, not an excavated wall.</p></div><div><blockquote>“${esc(D.mealClauses[1].quote)}”</blockquote><p>1 Corinthians 11:21 · WEB</p><p id="model-result">${rooms?'Separate rooms proposed.':'No room division specified.'} ${arrival?'Earlier and later arrivals proposed; their cause remains unknown.':'No arrival schedule supplied.'} Paul reports unequal eating, not a recovered seating plan.</p><p>Horrell challenges the familiar villa model; his abstract was reviewed, not the full article.</p>${external(D.investigationSources.horrell.url,D.investigationSources.horrell.title)}</div></div>`;
 if(id==='synagogue')html=`<div><div><p class="eyebrow">Inspect the find context</p><h4>A date on a coin.<br><em>A date for what?</em></h4>${D.layers.map((l,i)=>`<button data-layer="${i}" aria-pressed="${i===layer}">${esc(l.label)} ↓</button>`).join('')}<p>Compare contexts from the report; this is not one measured excavation section.</p></div><div id="layer-reading"><p class="eyebrow">${esc(D.layers[layer].date)}</p><h4>${esc(D.layers[layer].label)}</h4><p>${esc(D.layers[layer].observation)}</p><p>${esc(D.layers[layer].inference)}</p><p><b>Too far:</b> ${esc(D.layers[layer].excludes)}</p>${external(D.investigationSources.migdal.url,D.investigationSources.migdal.title)}</div></div>`;
 if(id==='ephesus')html=`<div><div><p class="eyebrow">Keep the dates attached</p><h4>One city.<br><em>Two public voices.</em></h4><button data-civic="0" aria-pressed="${civic===0}">Acts 19 · events in the 50s CE</button><button data-civic="1" aria-pressed="${civic===1}">Salutaris · 104 CE</button></div><div><p class="eyebrow">${civic?'104 CE · prescribed endowment':'50s CE · narrated events'}</p><h4>${civic?'A benefactor seeks civic honour.':'An official appeals to civic procedure.'}</h4><p>${civic?'The Salutaris inscription links Artemis’s images, the theatre and civic bodies. It records an authorised programme, not every performance.':'Acts 19 connects artisans’ livelihood, the honour of Artemis and a disputed public gathering. It is a narrative, not a court transcript.'}</p><p>The later inscription helps contextual comparison. It cannot verify Demetrius’s speech or the narrated crowd.</p>${civic?external(D.investigationSources.salutaris.url,D.investigationSources.salutaris.title):'<a href="http://127.0.0.1:8931/read/web/ACT/19?hl=23-41">Read Acts 19:23–41 →</a>'}</div></div>`;
 $('#investigation').innerHTML=html;
 if($('#rooms'))$('#rooms').onchange=e=>{rooms=e.target.checked;paintArt();save();$('#model-result').textContent=`${rooms?'Separate rooms proposed.':'No room division specified.'} ${arrival?'Earlier and later arrivals proposed; their cause remains unknown.':'No arrival schedule supplied.'} Paul reports unequal eating, not a recovered seating plan.`;};
 if($('#arrival'))$('#arrival').onchange=e=>{arrival=e.target.checked;save();$('#model-result').textContent=`${rooms?'Separate rooms proposed.':'No room division specified.'} ${arrival?'Earlier and later arrivals proposed; their cause remains unknown.':'No arrival schedule supplied.'} Paul reports unequal eating, not a recovered seating plan.`;};
 $('#investigation').onclick=e=>{const b=e.target.closest('button');if(b?.dataset.layer!==undefined){layer=+b.dataset.layer;renderInvestigation();save();$(`[data-layer="${layer}"]`).focus({preventScroll:true});}if(b?.dataset.civic!==undefined){civic=+b.dataset.civic;renderInvestigation();save();$(`[data-civic="${civic}"]`).focus({preventScroll:true});}};
}
$('#government').innerHTML=D.governments.map((g,i)=>`<option value="${i}">${esc(g.place)} · ${esc(g.date)}</option>`).join('');
function showGov(){const g=D.governments[+$('#government').value];$('#government-copy').innerHTML=`<h3>${esc(g.office)}</h3><p>${esc(g.text)}</p><p><b>Limit:</b> ${esc(g.limit)}</p>${g.source?external(D.sources[g.source].url,D.sources[g.source].label):''}<p><a href="${reader(g.passage)}">${esc(g.passage.label)}</a></p>`;}$('#government').onchange=showGov;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#reading').hidden)closeReading(true)});render();showGov();save();
